const config=JSON.parse(document.querySelector('#integration-data').textContent);
let analyticsStarted=false;
function loadAnalytics(){if(analyticsStarted||config.analytics.mode!=='ga4'||!/^G-[A-Z0-9]+$/.test(config.analytics.measurementId))return;analyticsStarted=true;window.dataLayer=window.dataLayer||[];function gtag(){window.dataLayer.push(arguments);}window.gtag=gtag;gtag('consent','default',{analytics_storage:'granted',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});gtag('js',new Date());gtag('config',config.analytics.measurementId,{send_page_view:false,allow_google_signals:false,allow_ad_personalization_signals:false});gtag('event','page_view',{page_location:location.origin+location.pathname,page_title:document.title,page_referrer:document.referrer?new URL(document.referrer).origin:''});window.copysprigTrack=(name,attrs={})=>{const allowed=new Set(['copy','favorite_toggle']);if(!allowed.has(name))return;const safe={};if(['style','symbol'].includes(attrs.item_kind))safe.item_kind=attrs.item_kind;if(typeof attrs.item_id==='string'&&/^(style:[a-z-]+|symbol:[a-z]+-\d+)$/.test(attrs.item_id))safe.item_id=attrs.item_id;gtag('event',name,safe);};const script=document.createElement('script');script.async=true;script.src=`https://www.googletagmanager.com/gtag/js?id=${config.analytics.measurementId}`;document.head.append(script);}
function consentValue(){try{return localStorage.getItem('copysprig-analytics-consent');}catch{return 'denied';}}
if(config.analytics.mode==='ga4'){
 const box=document.querySelector('#analytics-consent');box.hidden=consentValue()!==null;if(consentValue()==='granted')loadAnalytics();
 box.querySelector('[data-consent=allow]').addEventListener('click',()=>{try{localStorage.setItem('copysprig-analytics-consent','granted');}catch{}box.hidden=true;window[`ga-disable-${config.analytics.measurementId}`]=false;if(analyticsStarted){window.gtag?.('consent','update',{analytics_storage:'granted'});location.reload();}else loadAnalytics();});
 box.querySelector('[data-consent=decline]').addEventListener('click',()=>{try{localStorage.setItem('copysprig-analytics-consent','denied');}catch{}window.copysprigTrack=undefined;window[`ga-disable-${config.analytics.measurementId}`]=true;window.gtag?.('consent','update',{analytics_storage:'denied'});box.hidden=true;});
 document.querySelector('#privacy-settings')?.addEventListener('click',()=>{box.hidden=false;box.scrollIntoView({block:'center'});box.querySelector('button').focus();});
}
// Ads are inactive until a real publisher, slot, approval and certified CMP exist.
// An activated implementation waits for the site's consent bridge; it never
// treats analytics consent as advertising consent.
if(config.ads.enabled&&config.ads.cmpReady&&/^ca-pub-\d{16}$/.test(config.ads.publisherId)&&/^\d+$/.test(config.ads.slotId)){
 window.addEventListener('copysprig-ad-consent',e=>{if(e.detail?.allowed!==true||document.querySelector('script[data-copysprig-ads]'))return;const section=document.querySelector('#ad-placement');if(!section)return;section.hidden=false;const ad=document.createElement('ins');ad.className='adsbygoogle';ad.style.display='block';ad.dataset.adClient=config.ads.publisherId;ad.dataset.adSlot=config.ads.slotId;ad.dataset.adFormat='auto';ad.dataset.fullWidthResponsive='true';section.append(ad);const script=document.createElement('script');script.async=true;script.crossOrigin='anonymous';script.dataset.copysprigAds='true';script.src=`https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${config.ads.publisherId}`;script.onload=()=>{(window.adsbygoogle=window.adsbygoogle||[]).push({});};document.head.append(script);});
}
